import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Validate reportId is numeric
        if (reportId == null || !reportId.matches("\\d+")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Whitelist sort columns
        String[] allowedCols = {"created_at", "amount", "status", "customer_name"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedCols) {
                if (col.equals(sortCol)) { validSort = true; break; }
            }
        }
        if (!validSort) { sortCol = "created_at"; }

        // Direction validation - appears safe but isn't
        if (direction == null) { direction = "ASC"; }
        direction = direction.trim();
        // Developer assumed this regex catches injection but it allows
        // multi-line payloads and certain bypass patterns
        if (!direction.toUpperCase().startsWith("ASC") && 
            !direction.toUpperCase().startsWith("DESC")) {
            direction = "ASC";
        }

        String query = "SELECT r.id, r.created_at, r.amount, r.status, c.customer_name " +
                       "FROM reports r JOIN customers c ON r.customer_id = c.id " +
                       "WHERE r.report_group_id = " + reportId + " " +
                       "ORDER BY " + sortCol + " " + direction;

        log.info("Executing report query for group: " + reportId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",");
                sb.append(String.format(
                    "{\"id\":%d,\"created_at\":\"%s\",\"amount\":\"%.2f\",\"status\":\"%s\",\"customer\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getTimestamp("created_at").toString(),
                    rs.getDouble("amount"),
                    rs.getString("status"),
                    rs.getString("customer_name")
                ));
                first = false;
            }
            sb.append("]");
            resp.getWriter().write(sb.toString());
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
